Looking at the examples, I need to find which shapes get replaced by color 2.

**Key Insight:** The single `2` cell acts as a seed. Shapes (connected components of same non-zero color) get replaced if they're connected to the `2` cell through a chain where consecutive elements are separated by at most one `0` cell orthogonally. Shapes not in this chain stay unchanged. The original `2` cell becomes `0`.

The connection works via "0-cell bridges": a `0` cell adjacent to two different shape/2 nodes links them, as does direct orthogonal adjacency between different shapes.

```python
def solve(grid):
    rows, cols = len(grid), len(grid[0])
    pos2 = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                pos2 = (r, c)

    comp_id = [[None]*cols for _ in range(rows)]
    components = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] not in (0, 2) and comp_id[r][c] is None:
                color = grid[r][c]
                comp = []
                stack = [(r, c)]
                cid = len(components)
                comp_id[r][c] = cid
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols and comp_id[nr][nc] is None and grid[nr][nc] == color:
                            comp_id[nr][nc] = cid
                            stack.append((nr, nc))
                components.append(comp)

    n = len(components)
    adj = [set() for _ in range(n + 1)]

    def get_node(r, c):
        if (r, c) == pos2: return n
        if comp_id[r][c] is not None: return comp_id[r][c]
        return None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                neighbors = set()
                for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        nd = get_node(nr, nc)
                        if nd is not None:
                            neighbors.add(nd)
                neighbors = list(neighbors)
                for i in range(len(neighbors)):
                    for j in range(i+1, len(neighbors)):
                        adj[neighbors[i]].add(neighbors[j])
                        adj[neighbors[j]].add(neighbors[i])
            else:
                node1 = get_node(r, c)
                if node1 is not None:
                    for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            node2 = get_node(nr, nc)
                            if node2 is not None and node2 != node1:
                                adj[node1].add(node2)
                                adj[node2].add(node1)

    visited = [False] * (n + 1)
    visited[n] = True
    queue = [n]
    replace_set = set()
    while queue:
        node = queue.pop(0)
        if node != n:
            replace_set.add(node)
        for nb in adj[node]:
            if not visited[nb]:
                visited[nb] = True
                queue.append(nb)

    result = [row[:] for row in grid]
    result[pos2[0]][pos2[1]] = 0
    for cid in replace_set:
        for (r, c) in components[cid]:
            result[r][c] = 2
    return result
